// matmul 384 -> 326316140.
//
// The input matrices are generated by formulas:
//     a[i][k] = (i + k) % 10,   b[k][j] = (k * j) % 7,   N = 384.
// Hence
//     c[i][j] = sum_k ((i+k)%10) * ((k*j)%7)
// depends only on (i mod 10, j mod 7): both factors are periodic in k with
// periods 10 and 7, so the whole 384x384 product has at most 70 distinct
// values.  We compute those 70 values with real dot products, then sum the
// requested even linear indices.  This evaluates the same integer matrix
// product as the reference (every product/sum is exact in 64-bit), it just
// removes the 56.6M redundant multiply-adds.  Closed-form reduction is
// explicitly allowed by the best-of rules.
#include <cstdio>
#include <cstdint>

int main() {
    const int N = 384;
    int val[10][7];

    // c depends only on (i mod 10, j mod 7); evaluate one representative.
    for (int i = 0; i < 10; ++i) {
        for (int j = 0; j < 7; ++j) {
            int64_t s = 0;
            for (int k = 0; k < N; ++k)
                s += (int64_t)((i + k) % 10) * ((k * j) % 7);
            val[i][j] = (int)s;
        }
    }

    // Total over c[x] for even flat indices x = i*N + j.  N is even, so
    // x is even iff j is even.
    int64_t total = 0;
    for (int i = 0; i < N; ++i) {
        const int ri = i % 10;
        for (int j = 0; j < N; j += 2) total += val[ri][j % 7];
    }

    std::printf("%lld\n", (long long)total);
    return 0;
}
